def SRC(items):
    li = "".join(f'<li><a href="{u}" rel="nofollow noopener" target="_blank">{n}</a></li>' for n, u in items)
    return f"<h2>근거 자료 ({CHK})</h2><ul>{li}</ul>"


def TIP(t):
    return f'<div class="b-tip"><p><b>실전 팁</b> {t}</p></div>'


